            existingLease !== undefined &&
            existingLease.expiresAtEpochMillis > nowEpochMillis
          ) {
            return [false, currentLeases] as const;
          }

          const nextLeases = new Map([
            ...currentLeases,
            [
              lease.subjectHash,
              {
                owner: lease.owner,
                expiresAtEpochMillis: lease.expiresAtEpochMillis,
