const CodexOAuthProfileMemoryStateLayer = (
  profiles: readonly CodexOAuthProfileType[]
) =>
  Layer.effect(
    CodexOAuthProfileMemoryState,
    Effect.gen(function* makeCodexOAuthProfileMemoryState() {
      const entries = new Map<string, CodexOAuthProfileType>();

      for (const profile of profiles) {
        const key = yield* codexOAuthProfileStorageKey(profile.subject);
        entries.set(key, profile);
      }

      return yield* Ref.make(entries);
    })
  );

