  CodexOAuthProfileCommit,
  Effect.gen(function* makeCodexOAuthProfileCommitMemory() {
    const state = yield* CodexOAuthProfileMemoryState;

    const writeProfile = (
      operation: "initialWrite" | "refresh" | "markReauthenticationRequired",
      profile: CodexSubscriptionProfileType,
      expectedRevision?: CodexSubscriptionProfileType["credentialRevision"]
    ) =>
      Effect.gen(function* writeProfileCommit() {
        const key = yield* codexOAuthProfileStorageKey(profile.subject);
        const subjectHash = yield* codexOAuthProfileSubjectHash(profile.subject);
        const committed = yield* Ref.modify(state, (entries) => {
          const currentProfile = entries.get(key);

