+    const error = yield* Schema.decodeUnknownEffect(CodexSubscriptionProfile)({
+      profileVersion: 2,
+      profileKind: "subscription",
+      subject,
+      accessToken: "access-token-secret",
+      expiresAtEpochMillis: 1_700_000_060_000,
